// Provided for lab 14.2 as its benchmark baseline. You do not edit this file (Metal host
// side). It is lab 14.1's part B: do lab 14.1 first.
//
//   bool encodeRadixSortOneBitGlobal(id<MTLComputeCommandEncoder> enc, id<MTLBuffer> keys,
//                                    id<MTLBuffer> vals, id<MTLBuffer> tmpKeys,
//                                    id<MTLBuffer> tmpVals, id<MTLBuffer> bits,
//                                    id<MTLBuffer> scanScratch, uint32_t n)
//       Encodes all 32 passes (extract, the provided scan, scatter) into enc. Stable; the
//       result is in keys/vals. bits holds n + 1 entries, scanScratch scanScratchCount(n + 1).
//       Returns false if a kernel (its own or the scan's) does not build or cannot run 256
//       threads per threadgroup; the encoder's contents are then not a sort.
//
// All dispatches go into the one serial encoder the caller passes; each sees the previous
// one's writes (notes/today/ch02-facts.md C9).
#import <Metal/Metal.h>
#include <cstdint>
#include <string>

#include "pmpp/metal.h"

// Provided in scan_launch.mm.
bool encodeExclusiveScan(id<MTLComputeCommandEncoder> enc, id<MTLBuffer> data, uint32_t count, id<MTLBuffer> scratch);

static id<MTLComputePipelineState> onebitPipeline(const char* name) {
    // PMPP_METAL_SHARED_DIR is <chapter>/shared; this lab group's provided files are in shared-g11.
    return pmpp::metal::pipeline(std::string(PMPP_METAL_SHARED_DIR) + "-g11/onebit_global.metal", name);
}

bool encodeRadixSortOneBitGlobal(id<MTLComputeCommandEncoder> enc, id<MTLBuffer> keys, id<MTLBuffer> vals,
                                 id<MTLBuffer> tmpKeys, id<MTLBuffer> tmpVals, id<MTLBuffer> bits,
                                 id<MTLBuffer> scanScratch, uint32_t n) {
    const NSUInteger block = 256;
    id<MTLComputePipelineState> extract = onebitPipeline("onebit_global_extract");
    id<MTLComputePipelineState> scatter = onebitPipeline("onebit_global_scatter");
    if (!extract || !scatter || n == 0) {
        return false;
    }
    if (extract.maxTotalThreadsPerThreadgroup < block || scatter.maxTotalThreadsPerThreadgroup < block) {
        return false;
    }
    id<MTLBuffer> keysIn = keys, valsIn = vals, keysOut = tmpKeys, valsOut = tmpVals;
    for (uint32_t bit = 0; bit < 32; ++bit) {
        [enc setComputePipelineState:extract];
        [enc setBuffer:keysIn offset:0 atIndex:0];
        [enc setBuffer:bits offset:0 atIndex:1];
        [enc setBytes:&n length:sizeof(n) atIndex:2];
        [enc setBytes:&bit length:sizeof(bit) atIndex:3];
        [enc dispatchThreadgroups:MTLSizeMake((n + 1 + block - 1) / block, 1, 1)
            threadsPerThreadgroup:MTLSizeMake(block, 1, 1)];

        if (!encodeExclusiveScan(enc, bits, n + 1, scanScratch)) {
            return false;
        }

        [enc setComputePipelineState:scatter];
        [enc setBuffer:keysIn offset:0 atIndex:0];
        [enc setBuffer:valsIn offset:0 atIndex:1];
        [enc setBuffer:keysOut offset:0 atIndex:2];
        [enc setBuffer:valsOut offset:0 atIndex:3];
        [enc setBuffer:bits offset:0 atIndex:4];
        [enc setBytes:&n length:sizeof(n) atIndex:5];
        [enc setBytes:&bit length:sizeof(bit) atIndex:6];
        [enc dispatchThreadgroups:MTLSizeMake((n + block - 1) / block, 1, 1)
            threadsPerThreadgroup:MTLSizeMake(block, 1, 1)];

        id<MTLBuffer> swap = keysIn; keysIn = keysOut; keysOut = swap;
        swap = valsIn; valsIn = valsOut; valsOut = swap;
    }
    return true;
}
